/**
 * Files a template carries that are not its own editable design, told by their TEXT (the name test is
 * in `files.mjs`): JA Kinetic dry run, 15/10/2026. PURE.
 */

/**
 * Why a file is not the template's own editable design, read from its text, or null:
 * - a build output whose header says so (`Generated by … do not edit`, `@generated`); a header that
 *   only says "do not edit X from here" is not one:
 *   a rewrite there is lost on the next build;
 * - a bundled Bootstrap (its `/*! Bootstrap v5…` banner), the library's palette, not the template's;
 * - a minified script (one line holding nearly the whole file). A compressed stylesheet is kept: a
 *   template's own compiled CSS is often one line.
 * @param {string} text @param {string} kind
 */
export function skipByContent(text, kind) {
  const header = leadingComment(text)
  if (
    header &&
    (/@generated\b|\bauto-?generated\b|\bthis file is generated\b/i.test(header) ||
      (/\bgenerated\b/i.test(header) &&
        /\bdo not edit\b|edit the source|\brerun\b|\bregenerate\b/i.test(header)))
  )
    return 'generated file (its header says do not edit): change its source and rebuild'
  // the empty page a Joomla/WordPress folder carries so the server lists no directory

  const banner = /\/\*![\s*]*Bootstrap\s+v(\d+(?:\.\d+)*)/i.exec(text)
  if (banner && kind === 'css')
    return `bundled Bootstrap v${banner[1]} (library banner): the library's palette, not the template's`
  if (kind === 'script' && text.length > 2000) {
    const longest = text.split('\n').reduce((m, l) => Math.max(m, l.length), 0)
    if (longest >= 0.9 * text.length) return 'minified script (one line): a build output, not editable source'
  }
  return null
}

/** The first comment of a file when it opens the file (after `<?php`, `@charset`), else null. */
function leadingComment(text) {
  const head = text.slice(0, 2000).replace(/^\uFEFF?(\s*<\?php)?(\s*@charset[^;]*;)?\s*/i, '')
  const m = /^(\/\*[\s\S]*?\*\/|<!--[\s\S]*?-->|(?:\/\/[^\n]*\n\s*)+)/.exec(head)
  return m ? m[1] : null
}
